import React, { useState, useEffect } from 'react';
import { Phone, Lock, Check } from 'lucide-react';

export default function FloatingWidgets() {
  const [callRing, setCallRing] = useState(true);

  // Pulse the call button every 3 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      setCallRing((prev) => !prev);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <>
      {/* 1. Top-Right: Incoming Call / Contact Notification Card */}
      <div className="absolute -top-5 -right-4 sm:-right-10 z-20 bg-white/96 backdrop-blur-md px-4 py-3 rounded-2xl shadow-xl shadow-slate-900/8 border border-slate-100 flex items-center gap-3 animate-float hover:scale-105 transition-transform duration-300 min-w-[180px]">
        {/* Avatar */}
        <div className="relative w-9 h-9 rounded-full overflow-hidden border border-sky-100 shadow-xs shrink-0">
          <img
            src="https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=150"
            alt="Shruti"
            className="w-full h-full object-cover"
          />
        </div>
        {/* Content */}
        <div className="flex-1">
          <div className="flex items-center gap-1.5">
            {/* Blurred name placeholder lines */}
            <div className="h-2 w-16 bg-slate-200 rounded-full"></div>
          </div>
          <div className="flex items-center gap-1 mt-1">
            <div className="h-1.5 w-24 bg-slate-100 rounded-full"></div>
          </div>
        </div>
        {/* Checkmark */}
        <Check className="w-4 h-4 text-sky-500 shrink-0" />
      </div>

      {/* 2. Left: Emoji Reactions Floating Badge */}
      <div className="absolute top-[38%] -left-8 sm:-left-14 z-20 bg-white/96 backdrop-blur-md px-3.5 py-2.5 rounded-2xl shadow-xl shadow-slate-900/8 border border-slate-100 flex items-center gap-2 animate-float-delayed hover:scale-105 transition-transform duration-300">
        <span className="text-xl leading-none">🔥</span>
        <span className="text-xl leading-none">❤️</span>
      </div>

      {/* 3. Bottom-Center: Pulsing Call Button */}
      <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center gap-2">
        {/* Outer ripple rings */}
        <div className="relative flex items-center justify-center w-14 h-14">
          <span className="absolute w-14 h-14 rounded-full bg-sky-300/30 animate-ping"></span>
          <span className="absolute w-11 h-11 rounded-full bg-sky-400/20 animate-pulse"></span>
          <button className="relative w-10 h-10 rounded-full bg-white border border-slate-200 shadow-lg flex items-center justify-center text-sky-600 hover:bg-sky-50 hover:scale-110 active:scale-95 transition-all duration-200">
            <Phone className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* 4. Bottom-Right: End-to-End Encrypted Badge */}
      <div className="absolute bottom-6 -right-4 sm:-right-12 z-20 bg-white/96 backdrop-blur-md px-4 py-2 rounded-2xl shadow-lg shadow-slate-900/8 border border-slate-100 flex items-center gap-2 animate-float hover:scale-105 transition-transform duration-300">
        <Lock className="w-3.5 h-3.5 text-sky-600 shrink-0" />
        <span className="text-xs font-semibold text-sky-700 whitespace-nowrap">End-to-end encrypted</span>
      </div>
    </>
  );
}
